Conditional Mutations with if_else()
When you need to compute values based on a condition, use if_else():

gapminder |&gt;
  filter(year == 2007) |&gt;
  mutate(income_level = if_else(gdpPercap &gt; 10000, "high", "low")) |&gt;
  select(country, gdpPercap, income_level) |&gt;
  head(8)
#&gt; # A tibble: 8 × 3
#&gt;   country     gdpPercap income_level
#&gt;   &lt;fct&gt;           &lt;dbl&gt; &lt;chr&gt;       
#&gt; 1 Afghanistan      975. low         
#&gt; 2 Albania         5937. low         
#&gt; 3 Algeria         6223. low         
#&gt; # ℹ 5 more rows


In Lab 1 context: Flag anomalies in streamflow:

flow_data |&gt;
  mutate(is_low = if_else(discharge &lt; quantile(discharge, 0.1), TRUE, FALSE))

Pattern 1: Basic Markers + Popups

library(leaflet); library(sf)

# External data (not included here)
starbucks &lt;- read_csv("data/starbucks.csv") |&gt; 
  st_as_sf(coords = c("longitude", "latitude"), crs = 4326)

leaflet(starbucks) |&gt; 
  addProviderTiles(providers$CartoDB) |&gt; 
  addMarkers(popup = ~store_name, label = ~city)

Pattern 2: Clustering for Large Point Sets
When you have 1,000+ points, clustering auto-aggregates them at lower zoom levels:

leaflet(starbucks) |&gt; 
  addProviderTiles(providers$CartoDB) |&gt; 
  addMarkers(clusterOptions = markerClusterOptions())

Pattern 3: Custom Awesome Icons

icons &lt;- awesomeIcons(icon = 'coffee', markerColor = "green", library = 'fa')

leaflet(starbucks) |&gt; 
  addProviderTiles(providers$CartoDB) |&gt; 
  addAwesomeMarkers(icon = icons, popup = ~store_name)

Pattern 4: Color Ramps by Attribute

# Color circles by categorical attribute (e.g., city name)
pal &lt;- colorFactor(c("darkgreen", "navy"), domain = unique(starbucks$city))

leaflet(starbucks) |&gt; 
  addProviderTiles(providers$CartoDB) |&gt; 
  addCircleMarkers(
    color = ~pal(city), 
    fillOpacity = 0.5, 
    stroke = FALSE,
    popup = ~paste0(store_name, " (", city, ")")
  ) |&gt; 
  addLegend(pal = pal, values = ~city, title = "City")

Variation: Color by numeric field (e.g., elevation, population density):

# Continuous color ramp for numeric data
pal_num &lt;- colorNumeric(palette = "viridis", domain = starbucks$elevation)

leaflet(starbucks) |&gt; 
  addProviderTiles(providers$CartoDB) |&gt; 
  addCircleMarkers(
    radius = ~sqrt(elevation) / 20,     # size scaled by elevation
    color = ~pal_num(elevation),         # color scaled by elevation
    fillOpacity = 0.7,
    stroke = FALSE
  ) |&gt; 
  addLegend(pal = pal_num, values = ~elevation, title = "Elevation (m)")

Example: Magnitude-Colored Earthquake Points

library(freestiler)

# Create a style with data-driven color (magnitude → interpolated color ramp)
style &lt;- freestile() |&gt; 
  add_background(color = "#e8e4d6") |&gt; 
  add_vector_layer(
    id = "earthquakes",
    source = "earthquakes",      # must match your pmtiles source
    type = "circle",
    paint = list(
      # Data-driven color: interpolate based on 'magnitude' property
      "circle-color" = list(
        "type" = "exponential",
        "property" = "magnitude",
        "base" = 1.5,
        "colorSpace" = "interpolate",
        "stops" = list(
          list(3, "#1a1a1a"),     # magnitude 3 → dark gray
          list(5, "#ffd700"),     # magnitude 5 → gold
          list(8, "#ff4500")      # magnitude 8 → orangered
        )
      ),
      # Size proportional to magnitude
      "circle-radius" = list(
        "type" = "exponential",
        "property" = "magnitude",
        "base" = 1.5,
        "stops" = list(
          list(3, 4),             # mag 3 → small circle
          list(8, 15)             # mag 8 → large circle
        )
      ),
      "circle-opacity" = 0.8,
      "circle-stroke-color" = "#ffffff",
      "circle-stroke-width" = 1.5
    )
  )

# Write JSON for use in browser
jsonlite::write_json(style, "earthquake-style.json", pretty = TRUE, auto_unbox = TRUE)

Output JSON excerpt:
{
  "layers": [{
    "id": "earthquakes",
    "source": "earthquakes",
    "type": "circle",
    "paint": {
      "circle-color": {
        "property": "magnitude",
        "type": "exponential",
        "stops": [[3, "#1a1a1a"], [5, "#ffd700"], [8, "#ff4500"]]
      },
      "circle-radius": {
        "property": "magnitude",
        "type": "exponential",
        "stops": [[3, 4], [8, 15]]
      }
    }
  }]
}

